        a = row['option_a_ratings']
        b = row['option_b_ratings']
        resp = row['response']

        ttb_pred = None
        for i in range(4):
            if a[i] > b[i]:
                ttb_pred = 0
                break
            elif b[i] > a[i]:
                ttb_pred = 1
                break

        if ttb_pred is not None:
            if resp == ttb_pred:
                ttb_aligned += 1
            total += 1

    return ttb_aligned / total if total > 0 else 0.5

